``,
`{source:22:60} karşılıkta misli aşmama`,
``,
`{source:2:284} borç hükümlerinden sonra gizlinin de hesabı; {source:3:30} iyi ve kötü işlerin hazır bulunması; {source:3:161} gizlice alınan şeyin getirilmesi ve herkesin tam karşılık alması; {source:25:27} {source:25:28} o gün elçinin yolunu bırakmanın pişmanlığı; {source:50:22} gaflet örtüsünün kalkıp o günün görünmesi; {source:50:29} sözün değişmemesi ve kullara haksızlık edilmemesi; {source:82:9} kayıt sahnesinden önce dinin yalanlanması; {source:82:13} iyilerin nimet içindeki akıbeti; {source:84:6} emeğiyle Rabbe ulaşan insan; {source:89:24} önden iş göndermeyi dilemek; {source:99:4} {source:99:5} yerin Rabbin buyruğuyla haber vermesi; {source:100:9} mezarlardan çıkarılma`,
`{source:2:278} ribânın kalanını bırakma buyruğu; {source:5:1} akitleri yerine getirme; {source:5:44} ayetleri az bedelle satmadan hakla hükmetme; {source:6:51} toplanma öncesinde Allah'tan başka koruyucu ve şefaatçi bulunmaması; {source:6:71} hidayetten geri dönmeme; {source:6:72} Allah'a toplanma; {source:23:101} borudan sonra soy bağının kalkması; {source:24:37} ticaretin gün korkusunu unutturmaması; {source:40:18} yaklaşan günde zalime sözü dinlenen şefaatçi bulunmaması; {source:58:18} diriltilenlerin yalan yemininin açığa çıkması; {source:69:28} malın kötü hesaptan kurtarmaması; {source:74:48} şefaatin onlara yaramaması; {source:75:10} {source:75:11} {source:75:12} o gün kaçış bulunmayıp varışın Rabbe olması; {source:79:37} {source:79:38} yakın hayatı yeğleyen taşkın kişi; {source:79:40} {source:79:41} Rabbin huzurundan korkup arzuyu dizginlemenin karşıt akıbeti`
];
let patch="*** Begin Patch\n*** Update File: "+path+"\n";
for(let i=0;i<8;i++){
 if(!add[i])continue;
 let old=lines[i], neu=old.endsWith(".")?old.slice(0,-1)+"; "+add[i]+".":old+"; "+add[i]+".";
 if(i===1){
  neu=neu.replace("{source:23:116} dönüşü izleyen sözde Allah'ın gerçek hükümdar diye anılması","{source:23:115} {source:23:116} dönüşün amaçsız olmayışı ve Allah'ın gerçek hükümdarlığı");
  neu=neu.replace("{source:56:1} {source:56:2} büyük olayın gerçekleşmesi ve yalanlanamaması","{source:56:1} {source:56:2} {source:56:3} büyük olayın gerçekleşip kimini alçaltması kimini yükseltmesi");
  neu=neu.replace("{source:69:15} 'o gün' büyük olayın gerçekleşmesi","{source:69:13} {source:69:14} {source:69:15} {source:69:16} {source:69:17} sûrun ardından yerin ve göğün değişmesi, tahtın taşınması");
 }
 patch+="@@\n-"+old+"\n+"+neu+"\n";
}
