};
for(const old of oldv){const m=old.match(/^- ([0-9]+:[0-9]+):/);if(!m||!newv[m[1]])throw Error("unexpected verdict");patch+="@@\n-"+old+"\n+"+newv[m[1]]+"\n";}
patch+="*** End Patch";
